using System.Diagnostics;using System.Drawing;using System.Windows.Forms;using SobhanNotificationHub.Services;using SobhanNotificationHub.UI;
namespace SobhanNotificationHub.Tray;public sealed class TrayIconService:IDisposable{private NotifyIcon? _icon;private AppServices? _services;private string? _fallbackUrl;public void Initialize(AppServices services){_services=services;_icon=new NotifyIcon{Icon=SystemIcons.Information,Text="Sobhan Notification Hub",Visible=true};_icon.ContextMenuStrip=TrayMenuService.Build(this,services);_icon.DoubleClick+=(s,e)=>ShowMain();_icon.BalloonTipClicked+=(s,e)=>OpenUrl(_fallbackUrl);}public void SetConnected(string user){if(_icon is null)return;_icon.Text=Limit($"متصل: {user}");_icon.Icon=SystemIcons.Information;}public void SetWarning(){if(_icon is null)return;_icon.Text="اختلال موقت در اتصال";_icon.Icon=SystemIcons.Warning;}public void SetDisconnected(){if(_icon is null)return;_icon.Text="اتصال دستگاه معتبر نیست";_icon.Icon=SystemIcons.Error;}public void ShowFallback(string title,string body,string? url){if(_icon is null)return;_fallbackUrl=url;_icon.ShowBalloonTip(7000,Limit(title),Limit(body,250),ToolTipIcon.Info);}public void ShowMain()=>System.Windows.Application.Current.Dispatcher.Invoke(()=>{var w=System.Windows.Application.Current.Windows.OfType<MainWindow>().FirstOrDefault()??new MainWindow();w.Show();w.Activate();});public void ShowHistory()=>System.Windows.Application.Current.Dispatcher.Invoke(()=>new NotificationHistoryWindow().Show());public void ShowSettings()=>System.Windows.Application.Current.Dispatcher.Invoke(()=>new SettingsWindow().Show());public void ShowConnect()=>System.Windows.Application.Current.Dispatcher.Invoke(()=>new DeviceConnectWindow().Show());public void ShowAbout()=>System.Windows.Application.Current.Dispatcher.Invoke(()=>new AboutWindow().Show());public void OpenPanel(string path="/"){if(_services is null)return;OpenUrl(_services.Settings.SiteUrl.TrimEnd('/')+path);}private static void OpenUrl(string? url){if(Uri.TryCreate(url,UriKind.Absolute,out var uri)&&uri.Scheme==Uri.UriSchemeHttps)Process.Start(new ProcessStartInfo(uri.ToString()){UseShellExecute=true});}public void Exit()=>System.Windows.Application.Current.Dispatcher.Invoke(()=>System.Windows.Application.Current.Shutdown());private static string Limit(string value,int max=63)=>value.Length>max?value[..max]:value;public void Dispose(){if(_icon is null)return;_icon.Visible=false;_icon.Dispose();}}
